package org.jlinalg.cli;

import java.io.ByteArrayOutputStream;
import java.io.PrintStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.LinkedHashMap;
import java.util.Map;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import static org.junit.jupiter.api.Assertions.*;

class HomerAtacCliTest {
    @TempDir Path root;
    private Map<String,String> options(){var o=new LinkedHashMap<String,String>();o.put("home",root.resolve("missing-runtime").toString());o.put("profile","linux-x86_64-atac-5.1");o.put("out",root.resolve("result").toString());o.put("sam-list",root.resolve("unread.tsv").toString());o.put("reference-lengths",root.resolve("unread-reference.tsv").toString());o.put("reference-build","synthetic");o.put("reference-provenance","Synthetic unit test; no upstream analysis");for(String key:new String[]{"duplicate-alignments","supplementary-alignments","unpaired-alignments","improper-pairs"})o.put(key,"error");o.put("zero-template-length","error");o.put("identical-replicates","error");o.put("effective-genome-size","10000");o.put("genome-size-policy","error");o.put("peak-style","original-default");o.put("peak-local-fold","4");o.put("peak-clonal-fold","2");o.put("peak-tag-cap","auto");o.put("coverage-length-normalization","100");o.put("coverage-endpoints","extend");return o;}
    private int run(Map<String,String> options,ByteArrayOutputStream errors)throws Exception{Path file=root.resolve("options.json");Files.writeString(file,RegenieRuntime.json(options),StandardCharsets.UTF_8);return HomerAtacCli.run(new String[]{"--options-file",file.toString()},new PrintStream(new ByteArrayOutputStream(),true,StandardCharsets.UTF_8),new PrintStream(errors,true,StandardCharsets.UTF_8));}
    @Test void missingRuntimeSkipsWithoutAnalysisAndCreatesTheAdvertisedPartialDirectory()throws Exception{var errors=new ByteArrayOutputStream();assertEquals(3,run(options(),errors));Path result=root.resolve("result");assertTrue(Files.isDirectory(result.resolve("partial")));String status=Files.readString(result.resolve("analysis-status.json"));assertTrue(status.contains("skipped-unavailable-dependency-or-capability"));String warning=Files.readString(result.resolve("WARNINGS.md"));assertTrue(warning.contains("ANALYSIS SKIPPED"));assertTrue(warning.contains("Required action:"));assertTrue(errors.toString(StandardCharsets.UTF_8).contains("ANALYSIS SKIPPED"));assertFalse(Files.readString(result.resolve("session.json")).contains("\"process_"));assertFalse(Files.exists(result.resolve("coverage.bw")));}
    @Test void badScientificPolicyRetainsClearFailureAndPartialLocationBeforeRuntimeLaunch()throws Exception{var o=options();o.put("coverage-length-normalization","none");var errors=new ByteArrayOutputStream();assertEquals(2,run(o,errors));Path result=root.resolve("result");assertTrue(Files.isDirectory(result.resolve("partial")));assertTrue(Files.readString(result.resolve("WARNINGS.md")).contains("coverage-length-normalization"));assertTrue(errors.toString(StandardCharsets.UTF_8).contains("Required action:"));assertFalse(Files.readString(result.resolve("session.json")).contains("\"process_"));}
    @Test void existingUserDirectoryAndContentsArePreserved()throws Exception{Path result=Files.createDirectory(root.resolve("result"));Files.writeString(result.resolve("preserve.txt"),"user-data\n");var errors=new ByteArrayOutputStream();assertEquals(2,run(options(),errors));assertEquals("user-data\n",Files.readString(result.resolve("preserve.txt")));try(var files=Files.list(result)){assertEquals(1,files.count());}assertTrue(errors.toString(StandardCharsets.UTF_8).contains("NEW directory"));}
    @Test void unknownRawFlagsCannotEscapeTheTypedCommandSurface(){var errors=new ByteArrayOutputStream();assertEquals(2,HomerAtacCli.run(new String[]{"--unreviewed-raw-flags","bad"},new PrintStream(new ByteArrayOutputStream()),new PrintStream(errors,true,StandardCharsets.UTF_8)));assertTrue(errors.toString(StandardCharsets.UTF_8).contains("Unknown option"));assertFalse(Files.exists(root.resolve("result")));}
    @Test void unsafeOriginalShellWorkPathsAreRejectedBeforeAnyOriginalProgram()throws Exception{Path unsafe=Files.createDirectory(root.resolve("unsafe parent"));var failure=assertThrows(HomerRuntime.Unavailable.class,()->HomerAtacRuntime.work(unsafe));assertTrue(failure.getMessage().contains("Required action:"));assertTrue(failure.getMessage().contains("ASCII"));}
    @Test void outputCannotPopulateOrInvalidateAnAdmittedRuntimeDirectory()throws Exception{Path home=Files.createDirectory(root.resolve("home"));Files.writeString(home.resolve("preserve.json"),"user-runtime-marker\n");var o=options();o.put("home",home.toString());o.put("out",home.resolve("analysis").toString());var errors=new ByteArrayOutputStream();assertEquals(2,run(o,errors));assertFalse(Files.exists(home.resolve("analysis")));assertEquals("user-runtime-marker\n",Files.readString(home.resolve("preserve.json")));try(var files=Files.list(home)){assertEquals(1,files.count());}assertTrue(errors.toString(StandardCharsets.UTF_8).contains("nonnested"));}
}
